/**
 * The active tenant's lockup.
 *
 * A firm with a real vector logo gets it; the others get their name set in the
 * product's own face. That is deliberately not a placeholder graphic - a
 * typographic wordmark is a legitimate lockup, where an invented mark for a real
 * company would be worse than none.
 */
export function BrandLockup({
  height = 26,
  className,
  logo,
}: { height?: number; className?: string; logo?: string | null }) {
  const TENANT = useTenant();
  // An uploaded logo wins over the built-in mark: a firm that set one in
  // settings expects to see it, not the tenant default it replaced.
  if (logo) {
    return (
      <img
        src={logo}
        alt={TENANT.name}
        style={{ height }}
        className={cn("w-auto shrink-0", className)}
      />
    );
  }
  if (TENANT.mark === "skallars") return <SkallarsLockup height={height} className={className} />;
  // A firm with a real mark gets it beside the name; the rest get the name alone.
  if (TENANT.mark === "hitl") {
    return (
      <span className={cn("inline-flex shrink-0 items-center gap-2", className)}>
        <BrandMark size={Math.round(height * 0.95)} />
        <span
          className="font-display whitespace-nowrap tracking-[-0.01em]"
          style={{ fontSize: Math.round(height * 0.66), lineHeight: 1 }}
        >
          {TENANT.name}
        </span>
      </span>
    );
  }
  return (
    <span
      className={cn("font-display shrink-0 whitespace-nowrap tracking-[-0.01em]", className)}
      style={{ fontSize: Math.round(height * 0.72), lineHeight: 1 }}
    >
      {TENANT.name}
    </span>
  );
}
